const files = items;
if (!files || files.length === 0 || !files[0].json.id) {
  return [{ json: { queueEmpty: true } }];
}

// Sort alphabetically by name
files.sort((a, b) => {
  const nameA = (a.json.name || '').toLowerCase();
  const nameB = (b.json.name || '').toLowerCase();
  return nameA.localeCompare(nameB);
});

let originalName = files[0].json.name || 'video.mp4';
let cleanName = originalName.replaceAll(' ', '_');
if (!cleanName.toLowerCase().endsWith('.mp4')) {
  cleanName += '.mp4';
}

// Return the first item
return [{
  json: {
    queueEmpty: false,
    ...files[0].json,
    normalizedFilename: cleanName
  }
}];

const originalName = $('Select First Alphabetically').item.json.name || 'video.mp4';
const cleanName = $('Select First Alphabetically').item.json.normalizedFilename;
const rawTitle = originalName.replace(/\.[^.]+$/, '');
const videoTitle = rawTitle
  .replace(/[_\-]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const videoDescription = $('Select First Alphabetically').item.json.description || '';
const diskFilename = '/tmp/' + cleanName;
const scheduledSlot = 'Daily Schedule';

return [{
  json: {
    videoTitle,
    videoDescription,
    diskFilename,
    scheduledSlot
  }
}];

const rawOutput = items[0].json.output;
let clean = rawOutput
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

const start = clean.indexOf('{');
const end   = clean.lastIndexOf('}');
if (start === -1 || end === -1) {
  throw new Error('Gemini did not return valid JSON. Got: ' + rawOutput);
}
const data = JSON.parse(clean.substring(start, end + 1));

const rawTags   = data.youtubeTags || [];
const tagsArr   = Array.isArray(rawTags) ? rawTags : rawTags.split(',');

const lowerTags = tagsArr.map(t => t.trim().toLowerCase());
if (!lowerTags.includes('shorts')) tagsArr.unshift('shorts');

const seen = new Set();
const tagsString = tagsArr
  .map(t => t.trim().toLowerCase().substring(0, 30))
  .filter(t => { if (!t || seen.has(t)) return false; seen.add(t); return true; })
  .slice(0, 25)
  .join(',');

let title = (data.youtubeTitle || '').substring(0, 100);
if (!title.toLowerCase().includes('#shorts')) {
  title = title.substring(0, 91).trimEnd() + ' #Shorts';
}

let description = data.youtubeDescription || '';
if (!description.toLowerCase().includes('#shorts')) {
  description = description.trimEnd() + '\n#Shorts #YouTubeShorts';
}

const categoryId      = String(data.youtubeCategory || '15');
const defaultLanguage = data.defaultLanguage || 'en';

return [{
  json: {
    ...items[0].json,
    youtubeTitle: title,
    youtubeDescription: description,
    youtubeTags: tagsString,
    categoryId,
    defaultLanguage
  }
}];

const upload = items[0].json;
const videoId = $('YouTube Upload').first().json.id;
return [{
  json: {
    success: !upload.error,
    videoId,
    videoUrl: 'https://www.youtube.com/shorts/' + videoId,
    title: $('Parse Gemini JSON').first().json.youtubeTitle,
    uploadedAt: new Date().toISOString()
  }
}];

